		assertThatThrownBy(() -> mapper.converter(user)).isInstanceOfSatisfying(ValidacaoException.class,
				excecao -> {
					assertThat(excecao.getChave()).isEqualTo(chave);
					assertThat(excecao.getMensagem()).isEqualTo(mensagem);
				});
